+const cloudflareApiBaseUrl = "https://api.cloudflare.com/client/v4";
+
+export async function ensureQueues({
+  accountId = process.env.CLOUDFLARE_ACCOUNT_ID,
+  apiToken = process.env.CLOUDFLARE_API_TOKEN,
+  fetchImpl = globalThis.fetch,
+  queueNames,
+} = {}) {
+  requireNonEmptyString(accountId, "CLOUDFLARE_ACCOUNT_ID");
+  requireNonEmptyString(apiToken, "CLOUDFLARE_API_TOKEN");
+  if (!Array.isArray(queueNames) || queueNames.length === 0) {
+    throw new TypeError("queueNames must contain at least one queue name.");
+  }
+
+  const existingQueueNames = await listQueueNames({ accountId, apiToken, fetchImpl });
+
+  for (const queueName of queueNames) {
+    if (existingQueueNames.has(queueName)) {
+      continue;
+    }
+
+    try {
+      await createQueue({ accountId, apiToken, fetchImpl, queueName });
+    } catch (error) {
+      if (!(error instanceof CloudflareApiError) || error.status !== 409) {
+        throw error;
+      }
+
+      const queuesAfterConflict = await listQueueNames({ accountId, apiToken, fetchImpl });
+      if (!queuesAfterConflict.has(queueName)) {
+        throw error;
+      }
+    }
+  }
+}
+
+async function listQueueNames({ accountId, apiToken, fetchImpl }) {
+  const queueNames = new Set();
+  let page = 1;
+
+  while (true) {
+    const response = await cloudflareApiRequest({
+      accountId,
+      apiToken,
+      fetchImpl,
+      method: "GET",
+      path: `/accounts/${encodeURIComponent(accountId)}/queues?page=${page}&per_page=1000`,
+    });
+
+    if (!Array.isArray(response.result)) {
+      throw new Error("Cloudflare Queues API returned an invalid queue list.");
+    }
+
+    for (const queue of response.result) {
+      if (isRecord(queue) && typeof queue["queue_name"] === "string") {
+        queueNames.add(queue["queue_name"]);
+      }
+    }
+
+    const totalPages = isRecord(response.result_info) ? response.result_info["total_pages"] : 1;
+    if (typeof totalPages !== "number" || page >= totalPages) {
+      return queueNames;
+    }
+
+    page += 1;
+  }
+}
+
+async function createQueue({ accountId, apiToken, fetchImpl, queueName }) {
+  await cloudflareApiRequest({
+    accountId,
+    apiToken,
+    body: { queue_name: queueName },
+    fetchImpl,
+    method: "POST",
+    path: `/accounts/${encodeURIComponent(accountId)}/queues`,
+  });
+}
+
+async function cloudflareApiRequest({ apiToken, body, fetchImpl, method, path }) {
+  const response = await fetchImpl(`${cloudflareApiBaseUrl}${path}`, {
+    body: body === undefined ? undefined : JSON.stringify(body),
+    headers: {
+      accept: "application/json",
+      authorization: `Bearer ${apiToken}`,
+      ...(body === undefined ? {} : { "content-type": "application/json" }),
+    },
+    method,
+  });
+
+  let payload;
+  try {
+    payload = await response.json();
+  } catch {
+    payload = undefined;
+  }
+
+  if (!response.ok || !isRecord(payload) || payload["success"] !== true) {
+    throw new CloudflareApiError(response.status, apiErrorMessage(payload));
+  }
