+import assert from "node:assert/strict";
+import { test } from "node:test";
+import { ensureQueues } from "./ensure-queues.mjs";
+
+test("ensures missing queues without recreating existing queues", async () => {
+  const requests = [];
+  const response = async (input, init) => {
+    requests.push({ input: String(input), init });
+
+    if (init?.method === "POST") {
+      return Response.json({
+        result: { queue_name: "new-queue" },
+        success: true,
+      });
+    }
+
+    return Response.json({
+      result: [{ queue_name: "existing-queue" }],
+      result_info: { total_pages: 1 },
+      success: true,
+    });
+  };
+
+  await ensureQueues({
+    accountId: "account-id",
+    apiToken: "test-token",
+    fetchImpl: response,
+    queueNames: ["existing-queue", "new-queue"],
+  });
+
+  assert.equal(requests.length, 2);
+  assert.equal(requests[0].init.method, "GET");
+  assert.equal(requests[1].init.method, "POST");
+  assert.equal(
+    requests[1].input,
+    "https://api.cloudflare.com/client/v4/accounts/account-id/queues",
+  );
+  assert.equal(requests[1].init.body, JSON.stringify({ queue_name: "new-queue" }));
+  assert.equal(requests[1].init.headers.authorization, "Bearer test-token");
+});
+
+test("treats a concurrent create conflict as success when the queue exists", async () => {
+  let listCalls = 0;
+  const response = async (_input, init) => {
+    if (init?.method === "POST") {
+      return Response.json(
+        { errors: [{ message: "queue already exists" }], success: false },
+        { status: 409 },
+      );
+    }
+
+    listCalls += 1;
+    return Response.json({
+      result: listCalls === 1 ? [] : [{ queue_name: "new-queue" }],
+      result_info: { total_pages: 1 },
+      success: true,
+    });
+  };
+
+  await ensureQueues({
+    accountId: "account-id",
+    apiToken: "test-token",
+    fetchImpl: response,
+    queueNames: ["new-queue"],
+  });
+
+  assert.equal(listCalls, 2);
+});
+
+test("requires Cloudflare deployment credentials", async () => {
+  await assert.rejects(
+    ensureQueues({ queueNames: ["new-queue"], fetchImpl: async () => Response.json({}) }),
+    /CLOUDFLARE_ACCOUNT_ID must be configured/u,
+  );
+});

